alter table public.order_files add column if not exists deleted_at timestamptz;
alter table public.staff_settlements add column if not exists payment_amount bigint;
alter table public.staff_settlements add column if not exists payment_reference text;
alter table public.staff_settlements add column if not exists payment_paid_at timestamptz;
alter table public.staff_settlements add column if not exists payment_receipt_path text;
alter table public.staff_settlements add column if not exists payment_note text;
create index if not exists idx_order_files_cleanup on public.order_files(order_id, deleted_at);
drop function if exists public.admin_list_staff_settlements(text);
drop function if exists public.admin_update_staff_settlement(uuid,text,text);
create or replace function public.get_order_files_for_current_user(p_order_id uuid) returns setof public.order_files language plpgsql stable security definer set search_path to 'pg_catalog','public' as $$ declare v_uid uuid := auth.uid(); v_allowed boolean := false; begin if v_uid is null then raise exception 'ورود الزامی است'; end if; select exists(select 1 from public.orders o where o.id=p_order_id and (o.user_id=v_uid or o.assigned_staff_id=v_uid or public.is_admin())) into v_allowed; if not v_allowed then raise exception 'دسترسی به مدارک این سفارش مجاز نیست'; end if; return query select f.* from public.order_files f where f.order_id=p_order_id and f.deleted_at is null order by f.created_at asc; end; $$;
create function public.admin_list_staff_settlements(p_status text default null) returns table(id uuid,staff_id uuid,bank_account_id uuid,amount bigint,fee_amount bigint,net_amount bigint,status text,admin_note text,requested_at timestamptz,processed_at timestamptz,processed_by uuid,staff_name text,staff_email text,iban text,payment_amount bigint,payment_reference text,payment_paid_at timestamptz,payment_receipt_path text,payment_note text) language plpgsql security definer set search_path to 'public' as $$ begin if auth.uid() is null or not exists(select 1 from public.profiles p where p.id=auth.uid() and p.role='admin') then raise exception 'دسترسی غیرمجاز'; end if; return query select s.id,s.staff_id,s.bank_account_id,s.amount,s.fee_amount,s.net_amount,s.status,s.admin_note,s.requested_at,s.processed_at,s.processed_by,coalesce(p.full_name,'کاربر')::text,coalesce(u.email,'')::text,b.iban::text,s.payment_amount,s.payment_reference,s.payment_paid_at,s.payment_receipt_path,s.payment_note from public.staff_settlements s join public.profiles p on p.id=s.staff_id left join auth.users u on u.id=s.staff_id join public.staff_bank_accounts b on b.id=s.bank_account_id where p_status is null or s.status=p_status order by s.requested_at desc; end; $$;
create function public.admin_update_staff_settlement(p_settlement_id uuid,p_action text,p_note text default null,p_payment_amount bigint default null,p_payment_reference text default null,p_payment_paid_at timestamptz default null,p_payment_receipt_path text default null,p_payment_note text default null) returns public.staff_settlements language plpgsql security definer set search_path to 'public' as $$ declare v_admin uuid:=auth.uid(); v public.staff_settlements%rowtype; v_new text; begin if v_admin is null or not public.is_admin() then raise exception 'دسترسی غیرمجاز'; end if; perform pg_advisory_xact_lock(hashtextextended(p_settlement_id::text,0)); select * into v from public.staff_settlements where id=p_settlement_id for update; if not found then raise exception 'درخواست تسویه پیدا نشد'; end if; if p_action='approve' then if v.status<>'requested' then raise exception 'فقط درخواست در انتظار قابل تایید است'; end if; v_new:='approved'; elsif p_action='reject' then if v.status not in ('requested','approved','processing') then raise exception 'این درخواست قابل رد نیست'; end if; v_new:='rejected'; elsif p_action='processing' then if v.status<>'approved' then raise exception 'فقط درخواست تاییدشده قابل پردازش است'; end if; v_new:='processing'; elsif p_action='paid' then if v.status<>'processing' then raise exception 'فقط درخواست در حال پردازش قابل پرداخت است'; end if; if coalesce(p_payment_amount,v.net_amount)<>v.net_amount then raise exception 'مبلغ پرداخت باید برابر خالص تسویه باشد'; end if; if p_payment_reference is null or btrim(p_payment_reference)='' then raise exception 'شماره پیگیری پرداخت الزامی است'; end if; if p_payment_paid_at is null then raise exception 'تاریخ پرداخت الزامی است'; end if; if not exists(select 1 from public.staff_financial_adjustments a where a.reference_key='settlement:'||v.id::text and a.adjustment_type='settlement') then insert into public.staff_financial_adjustments(staff_id,order_id,amount,reason,created_by,adjustment_type,reference_key) values(v.staff_id,null,-v.amount,'تسویه درآمد مدیر سفارشات',v_admin,'settlement','settlement:'||v.id::text); end if; if not exists(select 1 from public.financial_transactions ft where ft.category='staff_settlement_fee' and ft.description='کارمزد تسویه سفارشات: '||v.id::text) then insert into public.financial_transactions(type,category,amount,description,date,created_by) values('income','staff_settlement_fee',v.fee_amount,'کارمزد تسویه سفارشات: '||v.id::text,current_date,v_admin); end if; update public.staff_settlements set payment_amount=v.net_amount,payment_reference=btrim(p_payment_reference),payment_paid_at=p_payment_paid_at,payment_receipt_path=coalesce(nullif(btrim(p_payment_receipt_path),''),payment_receipt_path),payment_note=coalesce(p_payment_note,payment_note) where id=v.id; v_new:='paid'; else raise exception 'عملیات نامعتبر است'; end if; update public.staff_settlements set status=v_new,admin_note=coalesce(p_note,admin_note),processed_at=case when v_new in ('rejected','paid') then now() else processed_at end,processed_by=v_admin where id=v.id returning * into v; return v; end; $$;
grant execute on function public.admin_update_staff_settlement(uuid,text,text,bigint,text,timestamptz,text,text) to authenticated;
grant execute on function public.admin_list_staff_settlements(text) to authenticated;
grant execute on function public.get_order_files_for_current_user(uuid) to authenticated;
